// ─────────────────────────────────────────────────────────────
// CLASS SKILLS — all 50 skills × 15 classes (750 total) as full
// SkillDef data, grouped by class. Tier-1 skills are playable in
// the current 1–5 level game; Tiers 2–5 are level-gated / passives
// locked behind higher levels (usable once the level system grows).
//
// Many "design-bible" effects (grapple, shove, banish, cooking,
// spirit summons, form-shifts) map onto the existing combat verbs:
// damage/heal/buff/condition/AoE. Where an effect can't be fully
// modeled yet it still exists as a SkillDef so the data is complete;
// the combat resolver uses the mapped fields.
// ─────────────────────────────────────────────────────────────
import type { Ability, ClassId, DamageType, SkillDef, SkillKind, ParticleFX } from './types';
import { minLevelForSkill } from './stats';

interface Spec {
  id: string; name: string; icon: string; desc: string;
  kind?: SkillKind; range?: number; aoeRadius?: number; cost?: 'action' | 'bonus' | 'free';
  cooldown?: number; ability?: Ability; dice?: string; dtype?: DamageType;
  healDice?: string; cond?: string; selfCentered?: boolean; allies?: boolean;
  selfOnly?: boolean; allAllies?: boolean; projectile?: boolean; fxColor?: number; fx?: ParticleFX;
  tier?: 1 | 2 | 3 | 4 | 5; levelReq?: number; passive?: boolean; apCost?: number;
  procsOncePerTurn?: boolean; stacking?: string; combo?: string[]; capstone?: boolean;
  appliesRounds?: number; summonId?: string; summonCount?: number; raiseCorpses?: 'one' | 'all';
}

function s(classId: ClassId, spec: Spec): SkillDef {
  return {
    id: spec.id,
    name: spec.name,
    icon: spec.icon,
    desc: spec.desc,
    kind: spec.kind ?? 'melee',
    range: spec.range ?? 1,
    aoeRadius: spec.aoeRadius ?? 0,
    cost: spec.cost ?? 'action',
    cooldown: spec.cooldown ?? 0,
    attackAbility: spec.ability ?? 'str',
    damageDice: spec.dice ?? '',
    damageType: spec.dtype ?? 'bludgeoning',
    healDice: spec.healDice,
    projectile: spec.projectile,
    fxColor: spec.fxColor ?? 0xffe08a,
    fx: spec.fx ?? 'slash',
    appliesCondition: spec.cond,
    appliesRounds: spec.appliesRounds,
    selfCentered: spec.selfCentered,
    targetsAllies: spec.allies,
    selfOnly: spec.selfOnly,
    allAllies: spec.allAllies,
    classId,
    tier: spec.tier ?? 1,
    levelReq: spec.levelReq ?? 1,
    passive: spec.passive,
    apCost: spec.apCost,
    procsOncePerTurn: spec.procsOncePerTurn,
    stacking: spec.stacking,
    combo: spec.combo,
    capstone: spec.capstone,
    summonId: spec.summonId,
    summonCount: spec.summonCount,
    raiseCorpses: spec.raiseCorpses,
  };
}

/** 10 skills per class per tier, all tiers 1..5 */
function tierT(classId: ClassId, tier: 1 | 2 | 3 | 4 | 5, specs: Spec[], cap?: Spec): SkillDef[] {
  const out: SkillDef[] = [];
  specs.forEach((sp, i) => {
    out.push(s(classId, { ...sp, id: sp.id, tier, levelReq: sp.levelReq ?? tier * 10 - 9 + i }));
  });
  if (cap) out.push(s(classId, { ...cap, tier: 5, levelReq: 50, capstone: true }));
  return out;
}

